solution.solution.js:
function toNumber(text) {
  if (text.trim() === "") return null;
  const n = Number(text);
  if (Number.isNaN(n)) return null;
  return n;
}

function volumeOr(volume, fallback) {
  return volume ?? fallback;
}

function setting(user, key, fallback) {
  return user?.settings?.[key] ?? fallback;
}

unitTests:
test("numbers from text", () => {
  checkEq(toNumber("42"), 42);
  checkEq(toNumber(" -3.5 "), -3.5);
  checkEq(toNumber("4x"), null);
  checkEq(toNumber(""), null);
  checkEq(toNumber("   "), null);
  checkEq(toNumber("0"), 0);
});

test("nullish defaults", () => {
  checkEq(volumeOr(0, 50), 0);
  checkEq(volumeOr(null, 50), 50);
  checkEq(volumeOr(undefined, 50), 50);
  checkEq(volumeOr(80, 50), 80);
});

test("optional chaining", () => {
  checkEq(setting({ settings: { theme: "dark" } }, "theme", "light"), "dark");
  checkEq(setting({ settings: {} }, "theme", "light"), "light");
  checkEq(setting({}, "theme", "light"), "light");
  checkEq(setting(null, "theme", "light"), "light");
  checkEq(setting({ settings: { size: 0 } }, "size", 12), 0);
});

